@classmethod
def from_message(
    cls,
    message: RequestsMessage,
    raw_args: str = '',
    **kwargs
):
    kind = infer_requests_message_kind(message)

    options = {
        option: param in raw_args
        for option, param in OPTION_TO_PARAM[kind].items()
    }
    options.update(kwargs)

    return cls(
        kind=kind,
        **options
    )

